def top_memory(lines, n):
    totals = {}
    for line in lines:
        parts = line.split()
        if len(parts) < 4:
            continue
        comm = " ".join(parts[3:])
        totals[comm] = totals.get(comm, 0) + int(parts[2])
    items = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))
    return [[comm, kb // 1024] for comm, kb in items[:n]]

