def exposed_ports(lines, allowed):
    found = set()
    for line in lines:
        parts = line.split()
        if len(parts) < 4:
            continue
        addr, _, port = parts[3].rpartition(":")
        if addr.startswith("127.") or addr == "[::1]":
            continue
        if int(port) not in allowed:
            found.add(int(port))
    return sorted(found)

