content.correct_answer:
def budget_status(slo, total, errors, days_passed, window_days):
    if total == 0:
        return {"burn_rate": 0.0, "spent_percent": 0.0, "status": "ok"}
    allowed = 1 - slo / 100
    burn = (errors / total) / allowed
    spent = burn * days_passed / window_days * 100
    burn_rate = round(burn, 2)
    spent_percent = round(spent, 1)
    if spent_percent >= 100:
        status = "freeze"
    elif burn_rate > 1:
        status = "risk"
    else:
        status = "ok"
    return {"burn_rate": burn_rate, "spent_percent": spent_percent, "status": status}

